    enonce: "<span dir=\"ltr\" class=\"expr pt\">ABE</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">E</span> بحيث <span dir=\"ltr\" class=\"expr pt\">AE = 5</span> و <span dir=\"ltr\" class=\"expr pt\">EB = 4.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 115 105\" width=\"115\" height=\"105\" xmlns=\"http://www.w3.org/2000/svg\"><g transform=\"translate(-45.5 -40.7)\"><line x1=\"135.7\" y1=\"122.1\" x2=\"67.9\" y2=\"122.1\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"67.9\" y1=\"122.1\" x2=\"67.9\" y2=\"67.9\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><line x1=\"67.9\" y1=\"67.9\" x2=\"135.7\" y2=\"122.1\" stroke=\"#2c3e50\" stroke-width=\"1.7\"/><polyline points=\"78.9,122.1 78.9,111.1 67.9,111.1\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"67.9\" cy=\"122.1\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"56.1\" y=\"135.5\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">E</text><circle cx=\"135.7\" cy=\"122.1\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"149.6\" y=\"131.7\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"67.9\" cy=\"67.9\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"59.9\" y=\"59.1\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text></g></svg><br>أحسب المسافة <span dir=\"ltr\" class=\"expr pt\">AB.</span>",
